        type ArrayBufferView = TypedArray | DataView;

        type NonSharedUint8Array = Uint8Array;
        type NonSharedUint8ClampedArray = Uint8ClampedArray;
        type NonSharedUint16Array = Uint16Array;
        type NonSharedUint32Array = Uint32Array;
